  if (payload.postar_stories !== undefined) postarStories = Boolean(payload.postar_stories);
} catch(e) {}

// Função auxiliar para aguardar processamento da Meta
async function aguardarContainer(containerId) {
  for (let i = 0; i < 30; i++) {
    await new Promise(r => setTimeout(r, 5000));
    const resStatus = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://graph.instagram.com/v21.0/${containerId}?fields=status_code,status&access_token=${INSTAGRAM_ACCESS_TOKEN}`,
      json: true
    });
    if (resStatus && resStatus.status_code === 'FINISHED') return true;
    if (resStatus && resStatus.status_code === 'ERROR') return false;
  }
  return false;
}

// 1. Publicar REELS (Feed + Aba Reels)
let reelId = null;
const resContainerReels = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://graph.instagram.com/v21.0/${INSTAGRAM_ACCOUNT_ID}/media`,
  body: {
    access_token: INSTAGRAM_ACCESS_TOKEN,
    media_type: 'REELS',
    video_url: videoUrl,
    caption: caption,
    share_to_feed: shareToFeed ? 'true' : 'false'
  },
  json: true
});

if (resContainerReels && resContainerReels.id) {
  const okReels = await aguardarContainer.call(this, resContainerReels.id);
  if (okReels) {
    const resPubReels = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://graph.instagram.com/v21.0/${INSTAGRAM_ACCOUNT_ID}/media_publish`,
      body: { access_token: INSTAGRAM_ACCESS_TOKEN, creation_id: resContainerReels.id },
      json: true
    });
    if (resPubReels && resPubReels.id) reelId = resPubReels.id;
  }
}

// 2. Publicar STORIES (Vídeo vertical no Story do Instagram)
let storiesId = null;
if (postarStories && reelId) {
  await new Promise(r => setTimeout(r, 3000));
  const resContainerStories = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://graph.instagram.com/v21.0/${INSTAGRAM_ACCOUNT_ID}/media`,
    body: {
      access_token: INSTAGRAM_ACCESS_TOKEN,
      media_type: 'STORIES',
      video_url: videoUrl
    },
    json: true
  });

  if (resContainerStories && resContainerStories.id) {
    const okStories = await aguardarContainer.call(this, resContainerStories.id);
    if (okStories) {
      const resPubStories = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://graph.instagram.com/v21.0/${INSTAGRAM_ACCOUNT_ID}/media_publish`,
